import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.math.BigDecimal;

/**
 * Eingangs-DTO für den Partner-Callback.
 * Bean Validation erzwingt Typ-, Bereichs- und Allow-List-Prüfungen,
 * bevor irgendein Wert die Service-Schicht erreicht.
