"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Order.java
package com.example.orders.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * JPA-Entity. Keine dynamische SQL-Erzeugung – alle Zugriffe erfolgen
 * über parametrisierte Queries des EntityManagers / Spring Data JPA.
 */
@Entity
@Table(name = "orders")
public class Order {

    @Id
    private Long id;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 32)
    private OrderStatus status;

    @Column(nullable = false, precision = 14, scale = 2)
    private BigDecimal amount;

    @Column(nullable = false, updatable = false)
    private Instant createdAt;

    @Column(nullable = false)
    private Instant updatedAt;

    /**
     * Optimistic Locking gegen verlorene Updates bei parallelen Callbacks.
     */
    @Version
    private Long version;

    protected Order() {
        // JPA
    }

    public Order(Long id, OrderStatus status, BigDecimal amount) {
        this.id = id;
        this.status = status;
        this.amount = amount;
        Instant now = Instant.now();
        this.createdAt = now;
        this.updatedAt = now;
    }

    public void applyCallback(OrderStatus newStatus, BigDecimal newAmount) {
        this.status = newStatus;
        this.amount = newAmount;
        this.updatedAt = Instant.now();
    }

    public Long getId() {
        return id;
    }

    public OrderStatus getStatus() {
        return status;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public Long getVersion() {
        return version;
    }
}
