 * (parametrisierte Queries). Dadurch ist CWE-89 / SQL-Injection ausgeschlossen,
 * solange keine nativen Queries mit String-Konkatenation hinzugefügt werden.
 */
@Repository
public interface OrderRepository extends JpaRepository<Order, Long> {
}
