"}, {"type": "CODE_BLOCK", "language": "java", "content": "// OrderService.java
package com.example.orders.service;

import com.example.orders.api.dto.OrderCallbackRequest;
import com.example.orders.domain.Order;
import com.example.orders.domain.OrderRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Fachlogik für Upsert. Alle Werte stammen aus dem bereits validierten DTO.
 * Keine String-Konkatenation in SQL – ausschließlich parametrisierte JPA-Aufrufe.
 */
@Service
public class OrderService {

    private final OrderRepository orderRepository;

    public OrderService(OrderRepository orderRepository) {
        this.orderRepository = orderRepository;
    }

    @Transactional
    public Order upsertFromCallback(OrderCallbackRequest request) {
        return orderRepository.findById(request.getOrderId())
                .map(existing -> {
                    existing.applyCallback(request.getStatus(), request.getAmount());
                    return existing;
                })
                .orElseGet(() -> {
                    Order created = new Order(
                            request.getOrderId(),
                            request.getStatus(),
                            request.getAmount()
                    );
                    return orderRepository.save(created);
                });
    }
}
