package com.example.orders.api;

import com.example.orders.api.dto.OrderCallbackRequest;
import com.example.orders.api.dto.OrderResponse;
import com.example.orders.domain.Order;
import com.example.orders.service.OrderService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * REST-Endpunkt für Partner-Callbacks.
 * - @Valid erzwingt Bean-Validation vor dem Service-Aufruf.
 * - Nur application/json, keine Query-Parameter für sensible Daten.
 * - Keine Reflektion von Roh-Eingaben in Fehlermeldungen (XSS-Minimierung).
 */
@RestController
@RequestMapping(path = "/api/v1/partner/callbacks", produces = MediaType.APPLICATION_JSON_VALUE)
public class PartnerCallbackController {

    private final OrderService orderService;

    public PartnerCallbackController(OrderService orderService) {
        this.orderService = orderService;
    }

    @PostMapping(consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<OrderResponse> handleOrderCallback(
            @Valid @RequestBody OrderCallbackRequest request) {

        Order order = orderService.upsertFromCallback(request);
        return ResponseEntity
                .status(HttpStatus.OK)
                .body(new OrderResponse(order));
    }
}
