"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.orders.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler;
import org.springframework.security.web.header.writers.XXssProtectionHeaderWriter;

/**
 * Spring-Security-Konfiguration.
 *
 * CSRF: Für browserbasierte Clients aktiv (CookieCsrfTokenRepository).
 * Partner-Systeme müssen den CSRF-Token aus dem Cookie lesen und
 * im Header "X-XSRF-TOKEN" mitsenden. Bei rein maschinellen Callbacks
 * mit mTLS oder HMAC-Signatur kann CSRF gezielt nur für diesen Pfad
 * deaktiviert und stattdessen eine starke Authentifizierung (API-Key,
 * mTLS, signierte Payloads) eingesetzt werden – hier bewusst streng belassen.
 *
 * XSS: Security-Header (X-XSS-Protection, Content-Security-Policy).
 * Session: STATELESS, da es sich um eine REST-API handelt.
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        CsrfTokenRequestAttributeHandler requestHandler = new CsrfTokenRequestAttributeHandler();
        // Das konkrete Token wird als Request-Attribut exponiert (für SPA/Partner-Clients).
        requestHandler.setCsrfRequestAttributeName("_csrf");

        http
            .sessionManagement(sm -> sm.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
            .csrf(csrf -> csrf
                .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
                .csrfTokenRequestHandler(requestHandler)
            )
            .authorizeHttpRequests(auth -> auth
                // Callback-Endpunkt: in Produktion zusätzlich per API-Key, mTLS oder HMAC absichern
                .requestMatchers(HttpMethod.POST, "/api/v1/partner/callbacks/**").authenticated()
                .anyRequest().denyAll()
            )
            .httpBasic(Customizer.withDefaults())
            .headers(headers -> headers
                .xssProtection(xss -> xss.headerValue(XXssProtectionHeaderWriter.HeaderValue.ENABLED_MODE_BLOCK))
                .contentSecurityPolicy(csp -> csp.policyDirectives("default-src 'none'; frame-ancestors 'none'"))
                .contentTypeOptions(Customizer.withDefaults())
                .frameOptions(frame -> frame.deny())
            );

        return http.build();
    }
}
